/**
 * Migrated portfolio (the real body of work), generated by scripts/migrate-portfolio.mjs
 * from portfolio.logodesignpartner.com into data/portfolio-items.json.
 *
 * Do not edit portfolio-items.json by hand for new work; add new records there with the same
 * shape, or extend `extraWork` below. Titles marked titleSource "derived" had no name in the
 * source, so they are labelled by category and numbered rather than given invented client names.
 */
import dataset from "./portfolio-items.json";
import { featuredWorkSlugs } from "./work-featured";

export const workCategories = dataset.categories;

/** Numbered display titles for records without a source name, e.g. "Abstract logo · 12". */
const counters = {};
export const work = dataset.items.map((item) => {
  if (item.titleSource !== "derived") return { ...item, displayTitle: item.title };
  counters[item.title] = (counters[item.title] || 0) + 1;
  return { ...item, displayTitle: `${item.title} · ${String(counters[item.title]).padStart(2, "0")}` };
});

const bySlug = new Map(work.map((w) => [w.slug, w]));

/** Gallery order: full-resolution images first, the small source card preview last. */
export function galleryImages(item) {
  return [...item.images].sort((a, b) => (a.role === "card") - (b.role === "card"));
}

export function getWork(slug) {
  return bySlug.get(slug) ?? null;
}

export function getCategory(id) {
  return workCategories.find((c) => c.id === id) ?? null;
}

export function workByCategory(id) {
  return work.filter((w) => w.category === id);
}

/** Previous/next within the same category, in source order. */
export function adjacentWork(item) {
  const list = workByCategory(item.category);
  const i = list.findIndex((w) => w.slug === item.slug);
  return { prev: i > 0 ? list[i - 1] : null, next: i < list.length - 1 ? list[i + 1] : null, index: i + 1, total: list.length };
}

/** Related: same industry first (logos), then same category, excluding the item itself. */
export function relatedWork(item, limit = 6) {
  const same = work.filter((w) => w.slug !== item.slug && w.category === item.category);
  const sameSub = item.subcategory ? same.filter((w) => w.subcategory === item.subcategory) : [];
  const rest = same.filter((w) => !sameSub.includes(w));
  // Rotate the remainder so neighbouring projects get different suggestions.
  const offset = item.sourceOrder % Math.max(rest.length, 1);
  return [...sameSub, ...rest.slice(offset), ...rest.slice(0, offset)].slice(0, limit);
}

export function featuredWork() {
  return featuredWorkSlugs.map(getWork).filter(Boolean);
}

/** Which migrated categories illustrate each service page. */
const serviceCategories = {
  "logo-design": ["logos"],
  "brand-identity": ["branding", "logos"],
  "graphic-design": ["graphic-design"],
  "social-media-design": ["social-media", "graphic-design"],
  "ui-ux-design": ["ui-ux", "web-design"],
  "website-design": ["web-design"],
  "website-development": ["web-design"],
  "ecommerce-development": ["web-design"],
  "wordpress-development": ["web-design"],
  "nextjs-development": ["web-design"],
  "landing-page-design": ["web-design"],
  "website-redesign": ["web-design"],
  seo: ["web-design"],
  "website-maintenance": ["web-design"],
};

export function workForService(serviceSlug, limit = 6) {
  const cats = serviceCategories[serviceSlug] ?? [];
  const featured = featuredWork().filter((w) => cats.includes(w.category));
  const named = work.filter((w) => cats.includes(w.category) && w.titleSource === "source" && !featured.includes(w));
  return [...featured, ...named].slice(0, limit);
}

/** Compact records for the client-side grid (keeps the RSC payload small). */
export function workIndex() {
  return work.map((w) => {
    // Prefer the full-resolution image (web cards from the source are only 480px wide).
    const t = w.images.find((i) => i.role === "full") ?? w.thumbnail;
    return {
    slug: w.slug,
    title: w.displayTitle,
    category: w.category,
    subcategory: w.subcategory ?? null,
    bg: w.background ?? null,
    thumb: { src: t.src, width: t.width, height: t.height },
  };
  });
}
